// Data contract between the engine (`BlutilsOutput`, Rust) and this viewer.
//
// `src/__fixtures__/blutils.contract.json` is a byte-for-byte copy of the
// golden generated by `blutils/core/tests/contract.rs`. Regenerate it there
// with `UPDATE_GOLDEN=1 cargo test -p blutils-core --test contract` and copy it
// here; the monorepo `contract.yml` workflow fails when the two copies differ.
import fs from "fs";
import path from "path";
import { Component, ReactNode } from "react";
import { act, screen } from "@testing-library/react";
import { renderWithRouter } from "@/test-utils";
import { Results } from "@/pages/@anon/Results";
import { BlutilsResult, Config, ConsensusBean, Result, Taxon } from "./BlutilsResult";

jest.mock("flowbite-react", () =>
  require("@/test-utils/flowbite-tooltip-mock").withInlineTooltip()
);

const CONTRACT_PATH = path.resolve(__dirname, "../__fixtures__/blutils.contract.json");

// <ui root>/../blutils/test/mock/output/zymo-mock (monorepo checkout only)
const ZYMO_PATH = path.resolve(
  __dirname,
  "../../../blutils/test/mock/output/zymo-mock/blutils.consensus.json"
);

// ? ---------------------------------------------------------------------------
// ? Expected TS keys, checked for exhaustiveness by `tsc`
// ? ---------------------------------------------------------------------------

// `true` only when `K` lists every key of `T` (`satisfies` rejects extra keys).
type Exhaustive<T, K extends readonly (keyof T)[]> = [Exclude<keyof T, K[number]>] extends [never]
  ? true
  : false;

type OptionalKeys<T> = { [K in keyof T]-?: {} extends Pick<T, K> ? K : never }[keyof T];

const OUTPUT_KEYS = ["results", "config"] as const satisfies readonly (keyof BlutilsResult)[];
const RESULT_KEYS = ["runId", "query", "taxon"] as const satisfies readonly (keyof Result)[];
const TAXON_KEYS = [
  "reachedRank",
  "maxAllowedRank",
  "identifier",
  "percIdentity",
  "bitScore",
  "taxonomy",
  "mutated",
  "singleMatch",
  "consensusBeans",
] as const satisfies readonly (keyof Taxon)[];
const CONSENSUS_BEAN_KEYS = [
  "rank",
  "identifier",
  "occurrences",
  "taxonomy",
  "accessions",
] as const satisfies readonly (keyof ConsensusBean)[];
const CONFIG_KEYS = [
  "blutilsVersion",
  "subjectReads",
  "taxon",
  "outFormat",
  "maxTargetSeqs",
  "percIdentity",
  "queryCov",
  "strand",
  "eValue",
  "wordSize",
] as const satisfies readonly (keyof Config)[];

// Adding a field to an interface without updating its list above fails `tsc`.
const EXHAUSTIVE: [
  Exhaustive<BlutilsResult, typeof OUTPUT_KEYS>,
  Exhaustive<Result, typeof RESULT_KEYS>,
  Exhaustive<Taxon, typeof TAXON_KEYS>,
  Exhaustive<ConsensusBean, typeof CONSENSUS_BEAN_KEYS>,
  Exhaustive<Config, typeof CONFIG_KEYS>,
] = [true, true, true, true, true];

const OPTIONAL_RESULT_KEYS = ["runId", "taxon"] as const satisfies readonly OptionalKeys<Result>[];
const OPTIONAL_TAXON_KEYS = ["maxAllowedRank"] as const satisfies readonly OptionalKeys<Taxon>[];

// Keys serialized by the engine but absent from the TS types, as
// `<object>.<key>`. Emptying this list is the "contract aligned" criterion.
const KNOWN_DRIFT = ["config.isConfig", "config.runId"] as const;

type ObjectName = "output" | "result" | "taxon" | "consensusBean" | "config";

const TS_KEYS: Record<ObjectName, readonly string[]> = {
  output: OUTPUT_KEYS,
  result: RESULT_KEYS,
  taxon: TAXON_KEYS,
  consensusBean: CONSENSUS_BEAN_KEYS,
  config: CONFIG_KEYS,
};

// ? ---------------------------------------------------------------------------
// ? Helpers
// ? ---------------------------------------------------------------------------

function load(file: string): BlutilsResult {
  return JSON.parse(fs.readFileSync(file, "utf8")) as BlutilsResult;
}

type Visited = { name: ObjectName; value: object };

function visit(output: BlutilsResult): Visited[] {
  const visited: Visited[] = [{ name: "output", value: output }];
  if (output.config) visited.push({ name: "config", value: output.config });
  for (const result of output.results) {
    visited.push({ name: "result", value: result });
    if (!result.taxon) continue;
    visited.push({ name: "taxon", value: result.taxon });
    for (const bean of result.taxon.consensusBeans ?? []) {
      visited.push({ name: "consensusBean", value: bean });
    }
  }
  return visited;
}

const sorted = (keys: Iterable<string>) => Array.from(new Set(keys)).sort();

function driftOf(name: ObjectName) {
  return KNOWN_DRIFT.filter((entry) => entry.startsWith(`${name}.`)).map(
    (entry) => entry.slice(name.length + 1)
  );
}

class ErrorBoundary extends Component<{ children: ReactNode }, { error: Error | null }> {
  state = { error: null as Error | null };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  render() {
    if (this.state.error) {
      return <div data-testid="boundary-error">{this.state.error.message}</div>;
    }
    return this.props.children;
  }
}

function fakeResponse(body: string) {
  return { ok: true, status: 200, text: () => Promise.resolve(body) } as unknown as Response;
}

// ? ---------------------------------------------------------------------------
// ? Tests
// ? ---------------------------------------------------------------------------

describe("BlutilsResult contract", () => {
  const contract = load(CONTRACT_PATH);
  const visited = visit(contract);

  test("the expected key lists cover every interface field", () => {
    expect(EXHAUSTIVE).toEqual([true, true, true, true, true]);
  });

  test("the golden exercises every object of the contract", () => {
    expect(sorted(visited.map((v) => v.name))).toEqual(sorted(Object.keys(TS_KEYS)));
  });

  test.each(Object.keys(TS_KEYS) as ObjectName[])(
    "%s keys equal the TS interface keys plus KNOWN_DRIFT",
    (name) => {
      const expected = sorted([...TS_KEYS[name], ...driftOf(name)]);
      for (const { value } of visited.filter((v) => v.name === name)) {
        expect(sorted(Object.keys(value))).toEqual(expected);
      }
    }
  );

  test("every KNOWN_DRIFT entry is still observed in the golden", () => {
    const observed = visited.flatMap(({ name, value }) =>
      Object.keys(value)
        .filter((key) => !TS_KEYS[name].includes(key))
        .map((key) => `${name}.${key}`)
    );
    expect(sorted(observed)).toEqual(sorted(KNOWN_DRIFT));
  });

  test("the golden carries the required consensus cases", () => {
    const taxa = contract.results.flatMap((r) => (r.taxon ? [r.taxon] : []));
    expect(contract.results.some((r) => r.taxon === null)).toBe(true);
    expect(
      taxa.some((t) => t.singleMatch && t.percIdentity === 100 && t.reachedRank === "strain")
    ).toBe(true);
    expect(taxa.some((t) => !t.singleMatch && t.maxAllowedRank)).toBe(true);
  });
});

describe("Results page consumes the contract golden", () => {
  test("the Table renders page 1 without error", async () => {
    const raw = fs.readFileSync(CONTRACT_PATH, "utf8");
    jest.spyOn(global, "fetch").mockResolvedValue(fakeResponse(raw));

    renderWithRouter(
      <ErrorBoundary>
        <Results />
      </ErrorBoundary>,
      { route: "/?p=https://x/blutils.contract.json" }
    );
    await screen.findByText("Page Size > 10", undefined, { timeout: 4000 });
    await act(async () => {});

    expect(screen.queryByTestId("boundary-error")).not.toBeInTheDocument();
    const body = screen.getByTestId("table-element").querySelector("tbody")!;
    const queries = Array.from(body.querySelectorAll("button")).map((b) => b.textContent);
    expect(queries).toEqual(load(CONTRACT_PATH).results.map((r) => r.query).sort());
  });
});

const describeZymo = fs.existsSync(ZYMO_PATH) ? describe : describe.skip;

describeZymo("legacy zymo v7.1.3 output (TC-08)", () => {
  test("is readable as BlutilsResult", () => {
    const zymo = load(ZYMO_PATH);
    const required = (name: ObjectName, optional: readonly string[]) =>
      TS_KEYS[name].filter((key) => !optional.includes(key));

    expect(zymo.results.length).toBeGreaterThan(0);
    for (const { name, value } of visit(zymo)) {
      const keys = Object.keys(value);
      expect(keys.filter((key) => !TS_KEYS[name].includes(key))).toEqual([]);

      const optional =
        name === "result" ? OPTIONAL_RESULT_KEYS : name === "taxon" ? OPTIONAL_TAXON_KEYS : [];
      expect(required(name, optional).filter((key) => !keys.includes(key))).toEqual([]);
    }
  });
});
